    30→static void adc_hw_calibration(adc_unit_t unit)
    31→{
    32→#if SOC_ADC_CALIBRATION_V1_SUPPORTED
    33→	adc_hal_calibration_init(unit);
    34→	for (int j = 0; j < SOC_ADC_ATTEN_NUM; j++) {
    35→		adc_calc_hw_calibration_code(unit, j);
    36→#if SOC_ADC_CALIB_CHAN_COMPENS_SUPPORTED
    37→		/* Load the channel compensation from efuse */
    38→		for (int k = 0; k < SOC_ADC_CHANNEL_NUM(unit); k++) {
    39→			adc_load_hw_calibration_chan_compens(unit, k, j);
    40→		}
    41→#endif /* SOC_ADC_CALIB_CHAN_COMPENS_SUPPORTED */
    42→	}
    43→#endif /* SOC_ADC_CALIBRATION_V1_SUPPORTED */
    44→}
