    46→/* Convert zephyr,gain property to the ESP32 attenuation */
    47→static inline int gain_to_atten(enum adc_gain gain, adc_atten_t *atten)
    48→{
    49→	switch (gain) {
    50→	case ADC_GAIN_1:
    51→		*atten = ADC_ATTEN_DB_0;
    52→		break;
    53→	case ADC_GAIN_4_5:
    54→		*atten = ADC_ATTEN_DB_2_5;
    55→		break;
    56→	case ADC_GAIN_1_2:
    57→		*atten = ADC_ATTEN_DB_6;
    58→		break;
    59→	case ADC_GAIN_1_4:
    60→		*atten = ADC_ATTEN_DB_12;
    61→		break;
    62→	default:
    63→		return -ENOTSUP;
    64→	}
    65→	return 0;
    66→}
