   224→static int adc_esp32_channel_setup(const struct device *dev, const struct adc_channel_cfg *cfg)
   225→{
   226→	const struct adc_esp32_conf *conf = (const struct adc_esp32_conf *)dev->config;
   227→	struct adc_esp32_data *data = (struct adc_esp32_data *)dev->data;
   228→	int err;
   229→
   230→	if (cfg->channel_id >= conf->channel_count) {
   231→		LOG_ERR("Unsupported channel id '%d'", cfg->channel_id);
   232→		return -ENOTSUP;
   233→	}
   234→
   235→	if (cfg->reference != ADC_REF_INTERNAL) {
   236→		LOG_ERR("Unsupported channel reference '%d'", cfg->reference);
   237→		return -ENOTSUP;
   238→	}
   239→
   240→	if (cfg->acquisition_time != ADC_ACQ_TIME_DEFAULT) {
   241→		LOG_ERR("Unsupported acquisition_time '%d'", cfg->acquisition_time);
   242→		return -ENOTSUP;
   243→	}
   244→
   245→	if (cfg->differential) {
   246→		LOG_ERR("Differential channels are not supported");
   247→		return -ENOTSUP;
   248→	}
   249→
   250→	if (gain_to_atten(cfg->gain, &data->attenuation[cfg->channel_id])) {
   251→		LOG_ERR("Unsupported gain value '%d'", cfg->gain);
   252→		return -ENOTSUP;
   253→	}
   254→
   255→#ifdef CONFIG_ADC_ESP32_DMA
   256→	err = adc_esp32_dma_channel_setup(dev, cfg);
   257→
   258→	if (err < 0) {
   259→		return err;
   260→	}
   261→#else
   262→	adc_atten_t old_atten = data->attenuation[cfg->channel_id];
   263→
   264→	adc_oneshot_hal_chan_cfg_t config = {
   265→		.atten = data->attenuation[cfg->channel_id],
   266→		.bitwidth = data->resolution[cfg->channel_id],
   267→	};
   268→
   269→	adc_oneshot_hal_channel_config(&data->hal, &config, cfg->channel_id);
   270→
   271→	if ((data->cal_handle[cfg->channel_id] == NULL) ||
   272→	    (data->attenuation[cfg->channel_id] != old_atten)) {
   273→#if ADC_CALI_SCHEME_CURVE_FITTING_SUPPORTED
   274→		adc_cali_curve_fitting_config_t cal_config = {
   275→			.unit_id = conf->unit,
   276→			.chan = cfg->channel_id,
   277→			.atten = data->attenuation[cfg->channel_id],
   278→			.bitwidth = data->resolution[cfg->channel_id],
   279→		};
   280→
   281→		LOG_DBG("Curve fitting calib [unit_id: %u, chan: %u, atten: %u, bitwidth: %u]",
   282→			conf->unit, cfg->channel_id, data->attenuation[cfg->channel_id],
   283→			data->resolution[cfg->channel_id]);
   284→
   285→		if (data->cal_handle[cfg->channel_id] != NULL) {
   286→			/* delete pre-existing calib scheme */
   287→			adc_cali_delete_scheme_curve_fitting(data->cal_handle[cfg->channel_id]);
   288→		}
   289→
   290→		adc_cali_create_scheme_curve_fitting(&cal_config,
   291→						     &data->cal_handle[cfg->channel_id]);
   292→#endif /* ADC_CALI_SCHEME_CURVE_FITTING_SUPPORTED */
   293→
   294→#if ADC_CALI_SCHEME_LINE_FITTING_SUPPORTED
   295→		adc_cali_line_fitting_config_t cal_config = {
   296→			.unit_id = conf->unit,
   297→			.atten = data->attenuation[cfg->channel_id],
   298→			.bitwidth = data->resolution[cfg->channel_id],
   299→#if CONFIG_SOC_SERIES_ESP32
   300→			.default_vref = data->meas_ref_internal
   301→#endif
   302→		};
   303→
   304→		LOG_DBG("Line fitting calib [unit_id: %u, chan: %u, atten: %u, bitwidth: %u]",
   305→			conf->unit, cfg->channel_id, data->attenuation[cfg->channel_id],
   306→			data->resolution[cfg->channel_id]);
   307→
   308→		if (data->cal_handle[cfg->channel_id] != NULL) {
   309→			/* delete pre-existing calib scheme */
   310→			adc_cali_delete_scheme_line_fitting(data->cal_handle[cfg->channel_id]);
   311→		}
   312→
   313→		adc_cali_create_scheme_line_fitting(&cal_config,
   314→						    &data->cal_handle[cfg->channel_id]);
   315→#endif /* ADC_CALI_SCHEME_LINE_FITTING_SUPPORTED */
   316→	}
   317→#endif /* CONFIG_ADC_ESP32_DMA */
   318→
   319→	/* GPIO config for ADC mode */
   320→
   321→	int io_num = adc_channel_io_map[conf->unit][cfg->channel_id];
   322→
   323→	if (io_num < 0) {
   324→		LOG_ERR("Channel %u not supported!", cfg->channel_id);
   325→		return -ENOTSUP;
   326→	}
   327→
   328→	struct gpio_dt_spec gpio = {
   329→		.port = conf->gpio_port,
   330→		.dt_flags = 0,
   331→		.pin = io_num,
   332→	};
   333→
   334→	err = gpio_pin_configure_dt(&gpio, GPIO_DISCONNECTED);
   335→
   336→	if (err) {
   337→		LOG_ERR("Error disconnecting io (%d)", io_num);
   338→		return err;
   339→	}
   340→
   341→	return 0;
   342→}
