   400→static DEVICE_API(adc, api_esp32_driver_api) = {
   401→	.channel_setup = adc_esp32_channel_setup,
   402→	.read = adc_esp32_read,
   403→#ifdef CONFIG_ADC_ASYNC
   404→	.read_async = adc_esp32_read_async,
   405→#endif /* CONFIG_ADC_ASYNC */
   406→	.ref_internal = ADC_ESP32_DEFAULT_VREF_INTERNAL,
   407→};
