   410→#define ADC_ESP32_CONF_INIT(n)                                                                     \
   411→	.dma_dev = DEVICE_DT_GET(DT_INST_DMAS_CTLR_BY_IDX(n, 0)),                                  \
   412→	.dma_channel = DT_INST_DMAS_CELL_BY_IDX(n, 0, channel)
   413→#else
   414→#define ADC_ESP32_CONF_INIT(n)
   415→#endif /* defined(SOC_GDMA_SUPPORTED) && SOC_GDMA_SUPPORTED */
