   417→#define ADC_ESP32_CHECK_CHANNEL_REF(chan)                                                          \
   418→	BUILD_ASSERT(DT_ENUM_HAS_VALUE(chan, zephyr_reference, adc_ref_internal),                  \
   419→		     "adc_esp32 only supports ADC_REF_INTERNAL as a reference");
   420→
   421→#define ESP32_ADC_INIT(inst)                                                                       \
   422→                                                                                                   \
   423→	DT_INST_FOREACH_CHILD(inst, ADC_ESP32_CHECK_CHANNEL_REF)                                   \
   424→                                                                                                   \
   425→	static const struct adc_esp32_conf adc_esp32_conf_##inst = {                               \
   426→		.clock_dev = DEVICE_DT_GET(DT_INST_CLOCKS_CTLR(inst)),                             \
   427→		.clock_subsys = (clock_control_subsys_t)DT_INST_CLOCKS_CELL(inst, offset),         \
   428→		.unit = DT_PROP(DT_DRV_INST(inst), unit) - 1,                                      \
   429→		.channel_count = DT_PROP(DT_DRV_INST(inst), channel_count),                        \
   430→		.gpio_port = DEVICE_DT_GET(DT_NODELABEL(gpio0)),                                   \
   431→		ADC_ESP32_CONF_INIT(inst)};                                                        \
   432→                                                                                                   \
   433→	static struct adc_esp32_data adc_esp32_data_##inst = {                                     \
   434→		.hal =                                                                             \
   435→			{                                                                          \
   436→				.dev = (adc_oneshot_soc_handle_t)DT_INST_REG_ADDR(inst),           \
   437→			},                                                                         \
   438→	};                                                                                         \
   439→                                                                                                   \
   440→	DEVICE_DT_INST_DEFINE(inst, adc_esp32_init, NULL, &adc_esp32_data_##inst,                  \
   441→			      &adc_esp32_conf_##inst, POST_KERNEL, CONFIG_ADC_INIT_PRIORITY,       \
   442→			      &api_esp32_driver_api);
   443→
   444→DT_INST_FOREACH_STATUS_OKAY(ESP32_ADC_INIT)
